addTerms([
 {id:"reliability",t:"Reliability",la:"",d:"Psychology",b:"The consistency of a measurement: the same result across occasions, raters or items.",p:"Kinds: test–retest (stability over time), inter-rater (agreement between clinicians, often expressed as kappa), internal consistency (e.g. Cronbach's alpha), parallel forms. Reliability limits validity: an inconsistent measure cannot measure accurately.",ex:"Two clinicians independently diagnosing the same patient (DSM-5 field trials, Regier et al., 2013).",where:"Psychometrics",ccc:"",conf:"Validity (whether the test measures what it claims).",rel:["validity","dsm"],lesson:"p12",alias:["reliability","kappa","test-retest","internal consistency"]},
 {id:"validity",t:"Validity",la:"",d:"Psychology",b:"Whether a test measures what it claims to measure, and whether the inferences drawn from it are justified.",p:"Kinds: content, criterion (concurrent, predictive), construct (convergent, discriminant). Modern accounts treat validity as a property of the interpretations and uses of scores, not of the test itself. Cross-cultural validity is central in South Africa (Employment Equity Act 55 of 1998, s.8).",ex:"A depression scale validated in English but used without adaptation in isiZulu.",where:"Psychometrics",ccc:"",conf:"Reliability.",rel:["reliability"],lesson:"p12",alias:["validity","construct validity","psychometric validity","cultural fairness"]},
 {id:"behavioural-activation",t:"Behavioural activation",la:"",d:"Psychology",b:"A therapy for depression that schedules valued, rewarding activity to break the cycle of withdrawal and low mood.",p:"Rooted in Lewinsohn's account of depression as low response-contingent positive reinforcement, and in Jacobson et al.'s component analysis of CBT. Meta-analysis: superior to controls, SMD −0.74 (Ekers et al., 2014; 26 RCTs).",ex:"Planning a short walk and a phone call to a friend each day, regardless of mood.",where:"Ekers et al. (2014)",ccc:"",conf:"'Just keep busy': BA targets valued activity and avoidance patterns.",rel:["acedia","sorrow"],lesson:"p13",alias:["behavioural activation","behavioral activation","BA"]},
 {id:"exposure-therapy",t:"Exposure therapy",la:"",d:"Psychology",b:"Systematic, repeated contact with feared situations, images or sensations, without escape or safety behaviours, until fear lessens and new learning occurs.",p:"Explained by habituation and, more recently, inhibitory learning (a new 'safe' association competes with the old fear memory). Core in treating phobias, panic, social anxiety, OCD (as ERP) and PTSD (prolonged exposure).",ex:"A person with panic disorder deliberately inducing a racing heart by running on the spot.",where:"Carpenter et al. (2018)",ccc:"",conf:"Flooding without consent or preparation.",rel:["fortitude","erp"],lesson:"p14",alias:["exposure","exposure therapy","habituation","inhibitory learning"]},
 {id:"erp",t:"Exposure and response prevention (ERP)",la:"",d:"Psychology",b:"The first-line psychological treatment for OCD: facing obsessional triggers while refraining from compulsions and reassurance-seeking.",p:"CBT for OCD (mostly ERP) vs waiting list: g = 1.31 (Öst et al., 2015; 37 RCTs). In scrupulosity, compulsions include repeated confession, praying 'until it feels right', and seeking reassurance from priests.",ex:"Deliberately saying a prayer once, imperfectly, and not repeating it.",where:"Öst et al. (2015)",ccc:"",conf:"Mere reassurance, which feeds OCD.",rel:["scrupulosity","exposure-therapy"],lesson:"p15",alias:["ERP","exposure and response prevention","response prevention"]}
]);

